using System.Diagnostics;using System.Runtime.InteropServices;namespace Midl.Integration.Tests;/// <summary>/// End-to-end test that validates the full proxy/stub codegen pipeline:///   IDL ΓåÆ header + proxy code ΓåÆ compile server DLL + proxy DLL ΓåÆ cross-apartment call.////// Runs the build-and-test.ps1 script which:///   1. Generates code from IDL using our CLI///   2. Compiles server DLL, proxy DLL, and test client///   3. Registers COM classes (per-user, no admin)///   4. Runs TestClient.exe which exercises proxy/stub across STAΓåöMTA///   5. Unregisters and reports results/// </summary>public partial class E2EInProcMarshalTests{    private static readonly string ScriptPath = Path.Combine(        FindRepoRoot(), "tests", "e2e-custom-marshal", "inproc", "build-and-test.ps1");    [SkippableFact]    public void InProcProxyStub_CrossApartment_RoundTrips()    {        Skip.IfNot(RuntimeInformation.IsOSPlatform(OSPlatform.Windows),            "In-proc COM test requires Windows");        Skip.IfNot(File.Exists(ScriptPath),            $"Build script not found: {ScriptPath}");        Skip.IfNot(HasMsvcToolchain(),            "MSVC toolchain not found (vswhere/cl.exe)");        var psi = new ProcessStartInfo        {            FileName = "pwsh",            Arguments = $"-NoProfile -ExecutionPolicy Bypass -File \"{ScriptPath}\"",            WorkingDirectory = Path.GetDirectoryName(ScriptPath)!,            RedirectStandardOutput = true,            RedirectStandardError = true,            UseShellExecute = false,            CreateNoWindow = true,        };        // Fall back to Windows PowerShell if pwsh isn't available        if (!IsOnPath("pwsh"))        {            psi.FileName = "powershell";        }        using var process = Process.Start(psi)!;        var stdout = process.StandardOutput.ReadToEnd();        var stderr = process.StandardError.ReadToEnd();        process.WaitForExit(TimeSpan.FromMinutes(5));        // Output for diagnostics        if (stdout.Length > 0)            Console.Write(stdout);        if (stderr.Length > 0)            Console.Error.Write(stderr);        Assert.True(process.ExitCode == 0,            $"build-and-test.ps1 failed with exit code {process.ExitCode}.\n" +            $"stdout:\n{stdout}\nstderr:\n{stderr}");        Assert.Contains("PASS:", stdout);        Assert.DoesNotContain("FAIL:", stdout);    }    private static bool HasMsvcToolchain()    {        var vswhere = Path.Combine(            Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),            "Microsoft Visual Studio", "Installer", "vswhere.exe");        if (!File.Exists(vswhere))        {            vswhere = Path.Combine(                Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),                "Microsoft Visual Studio", "Installer", "vswhere.exe");        }        return File.Exists(vswhere);    }    private static bool IsOnPath(string exe)    {        try        {            var psi = new ProcessStartInfo            {                FileName = exe,                Arguments = "--version",                RedirectStandardOutput = true,                RedirectStandardError = true,                UseShellExecute = false,                CreateNoWindow = true,            };            using var p = Process.Start(psi);            p?.WaitForExit(5000);            return p?.ExitCode == 0;        }        catch        {            return false;        }    }    private static string FindRepoRoot()    {        var dir = AppContext.BaseDirectory;        while (dir != null)        {            if (File.Exists(Path.Combine(dir, "Midl.slnx")))                return dir;            dir = Path.GetDirectoryName(dir);        }        // Fallback: relative from test project        return Path.GetFullPath(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", ".."));    }}